1	using System.Data;
2	using System.Text.RegularExpressions;
3	using Microsoft.EntityFrameworkCore;
4	using seed_a_backend.Api.Data;
5	using seed_a_backend.Api.Dtos;
6	using seed_a_backend.Api.Models;
7	
8	namespace seed_a_backend.Api.Services;
9	
10	public partial class BuchungService(AppDbContext context) : IBuchungService
11	{
12	    private const string ReferenzZeichen = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // ohne verwechselbare Zeichen (I,O,0,1)
13	
14	    public async Task<BuchungDto> CreateBuchungAsync(CreateBuchungRequestDto request, CancellationToken cancellationToken = default)
15	    {
16	        ValidateStammdaten(request);
17	
18	        var veranstaltung = await context.Veranstaltungen
19	            .Include(v => v.Raum)
20	            .Include(v => v.Preiskategorien)
21	            .FirstOrDefaultAsync(v => v.Id == request.VeranstaltungId, cancellationToken)
22	            ?? throw new NotFoundException($"Veranstaltung '{request.VeranstaltungId}' wurde nicht gefunden.");
23	
24	        var raum = veranstaltung.Raum!;
25	        var gueltigeReihen = raum.Reihen.ToHashSet();
26	        var gangSet = raum.GangSpalten.ToHashSet();
27	        var preiskategorien = veranstaltung.Preiskategorien.ToDictionary(p => p.Id);
28	
29	        var angefragteSitzplaetze = new HashSet<(string Reihe, int Spalte)>();
30	        foreach (var sitzplatz in request.Sitzplaetze)
31	        {
32	            if (!gueltigeReihen.Contains(sitzplatz.Reihe) || sitzplatz.Spalte < 1 || sitzplatz.Spalte > raum.Spalten)
33	            {
34	                throw new ValidationException($"Sitzplatz '{sitzplatz.Reihe}{sitzplatz.Spalte}' existiert nicht in diesem Raum.");
35	            }
36	
37	            if (gangSet.Contains(sitzplatz.Spalte))
38	            {
39	                throw new ValidationException($"'{sitzplatz.Reihe}{sitzplatz.Spalte}' ist ein Gang und kein Sitzplatz.");
40	            }
41	
42	            if (!preiskategorien.ContainsKey(sitzplatz.PreiskategorieId))
43	            {
44	                throw new ValidationException($"Preiskategorie '{sitzplatz.PreiskategorieId}' gehört nicht zu dieser Veranstaltung.");
45	            }
46	
47	            if (!angefragteSitzplaetze.Add((sitzplatz.Reihe, sitzplatz.Spalte)))
48	            {
49	                throw new ValidationException($"Sitzplatz '{sitzplatz.Reihe}{sitzplatz.Spalte}' wurde mehrfach ausgewählt.");
50	            }
51	        }
52	
53	        await using var transaction = await context.Database.BeginTransactionAsync(IsolationLevel.Serializable, cancellationToken);
54	        try
55	        {
56	            var bereitsBelegt = await context.BuchungsPositionen
57	                .Where(p => p.VeranstaltungId == veranstaltung.Id && p.Aktiv)
58	                .Select(p => new { p.Reihe, p.Spalte })
59	                .ToListAsync(cancellationToken);
60	
61	            var belegtSet = bereitsBelegt.Select(p => (p.Reihe, p.Spalte)).ToHashSet();
62	            var konflikte = angefragteSitzplaetze.Where(belegtSet.Contains).ToList();
63	            if (konflikte.Count > 0)
64	            {
65	                throw new SeatConflictException(konflikte);
66	            }
67	
68	            var buchung = new Buchung
69	            {
70	                Referenz = await NeueEindeutigeReferenzAsync(cancellationToken),
71	                Name = request.Name.Trim(),
72	                Email = request.Email.Trim(),
73	                VeranstaltungId = veranstaltung.Id,
74	                Status = BuchungStatus.Bestaetigt,
75	                ErstelltAm = DateTime.UtcNow
76	            };
77	
78	            foreach (var sitzplatz in request.Sitzplaetze)
79	            {
80	                var preiskategorie = preiskategorien[sitzplatz.PreiskategorieId];
81	                buchung.Positionen.Add(new BuchungsPosition
82	                {
83	                    VeranstaltungId = veranstaltung.Id,
84	                    Reihe = sitzplatz.Reihe,
85	                    Spalte = sitzplatz.Spalte,
86	                    PreiskategorieId = preiskategorie.Id,
87	                    Preis = preiskategorie.Preis,
88	                    Aktiv = true
89	                });
90	            }
91	
92	            context.Buchungen.Add(buchung);
93	
94	            try
95	            {
96	                await context.SaveChangesAsync(cancellationToken);
97	            }
98	            catch (DbUpdateException)
99	            {
100	                // Ein anderer Vorgang hat zwischen Prüfung und Speichern denselben Platz belegt.
101	                throw new SeatConflictException(angefragteSitzplaetze.ToList());
102	            }
103	
104	            await transaction.CommitAsync(cancellationToken);
105	
106	            return ToDto(buchung, veranstaltung, preiskategorien);
107	        }
108	        catch
109	        {
110	            await transaction.RollbackAsync(cancellationToken);
111	            throw;
112	        }
113	    }
114	
115	    public async Task<BuchungDto> GetByReferenzAsync(string referenz, CancellationToken cancellationToken = default)
116	    {
117	        var buchung = await LoadBuchungAsync(referenz, cancellationToken);
118	        return ToDto(buchung, buchung.Veranstaltung!, buchung.Veranstaltung!.Preiskategorien.ToDictionary(p => p.Id));
119	    }
120	
121	    public async Task<BuchungDto> StornierenAsync(string referenz, CancellationToken cancellationToken = default)
122	    {
123	        var buchung = await LoadBuchungAsync(referenz, cancellationToken);
124	
125	        if (buchung.Status == BuchungStatus.Storniert)
126	        {
127	            throw new ValidationException("Diese Buchung wurde bereits storniert.");
128	        }
129	
130	        buchung.Status = BuchungStatus.Storniert;
131	        foreach (var position in buchung.Positionen)
132	        {
133	            position.Aktiv = false;
134	        }
135	
136	        await context.SaveChangesAsync(cancellationToken);
137	
138	        return ToDto(buchung, buchung.Veranstaltung!, buchung.Veranstaltung!.Preiskategorien.ToDictionary(p => p.Id));
139	    }
140	
141	    private async Task<Buchung> LoadBuchungAsync(string referenz, CancellationToken cancellationToken)
142	    {
143	        return await context.Buchungen
144	            .Include(b => b.Positionen)
145	            .Include(b => b.Veranstaltung!).ThenInclude(v => v.Preiskategorien)
146	            .FirstOrDefaultAsync(b => b.Referenz == referenz, cancellationToken)
147	            ?? throw new NotFoundException($"Buchung mit Referenz '{referenz}' wurde nicht gefunden.");
148	    }
149	
150	    private static void ValidateStammdaten(CreateBuchungRequestDto request)
151	    {
152	        if (string.IsNullOrWhiteSpace(request.VeranstaltungId))
153	        {
154	            throw new ValidationException("Veranstaltung ist erforderlich.");
155	        }
156	
157	        if (string.IsNullOrWhiteSpace(request.Name))
158	        {
159	            throw new ValidationException("Name ist erforderlich.");
160	        }
161	
162	        if (string.IsNullOrWhiteSpace(request.Email) || !EmailPattern().IsMatch(request.Email))
163	        {
164	            throw new ValidationException("Eine gültige E-Mail-Adresse ist erforderlich.");
165	        }
166	
167	        if (request.Sitzplaetze is null || request.Sitzplaetze.Count == 0)
168	        {
169	            throw new ValidationException("Es muss mindestens ein Sitzplatz ausgewählt werden.");
170	        }
171	    }
172	
173	    private async Task<string> NeueEindeutigeReferenzAsync(CancellationToken cancellationToken)
174	    {
175	        for (var versuch = 0; versuch < 10; versuch++)
176	        {
177	            var kandidat = GeneriereReferenz();
178	            var existiert = await context.Buchungen.AnyAsync(b => b.Referenz == kandidat, cancellationToken);
179	            if (!existiert)
180	            {
181	                return kandidat;
182	            }
183	        }
184	
185	        throw new InvalidOperationException("Es konnte keine eindeutige Buchungsreferenz erzeugt werden.");
186	    }
187	
188	    private static string GeneriereReferenz()
189	    {
190	        Span<char> buffer = stackalloc char[8];
191	        for (var i = 0; i < buffer.Length; i++)
192	        {
193	            buffer[i] = ReferenzZeichen[Random.Shared.Next(ReferenzZeichen.Length)];
194	        }
195	
196	        return new string(buffer);
197	    }
198	
199	    private static BuchungDto ToDto(Buchung buchung, Veranstaltung veranstaltung, IReadOnlyDictionary<string, Preiskategorie> preiskategorien)
200	    {
201	        var positionen = buchung.Positionen
202	            .OrderBy(p => p.Reihe).ThenBy(p => p.Spalte)
203	            .Select(p => new BuchungspositionDto(
204	                p.Reihe,
205	                p.Spalte,
206	                p.PreiskategorieId,
207	                preiskategorien.TryGetValue(p.PreiskategorieId, out var pk) ? pk.Name : p.PreiskategorieId,
208	                p.Preis))
209	            .ToList();
210	
211	        return new BuchungDto(
