1	import { CommonModule } from '@angular/common';
2	import { HttpErrorResponse } from '@angular/common/http';
3	import { Component, computed, inject, signal } from '@angular/core';
4	import { FormsModule } from '@angular/forms';
5	import { ActivatedRoute, Router, RouterLink } from '@angular/router';
6	import { BuchungenService } from '../../core/services/buchungen.service';
7	import { VeranstaltungenService } from '../../core/services/veranstaltungen.service';
8	import { ApiProblem, Sitzplan, Sitzplatz, VeranstaltungDetail } from '../../core/models/api.models';
9	
10	interface AusgewaehlterSitzplatz {
11	  reihe: string;
12	  spalte: number;
13	  preiskategorieId: string;
14	}
15	
16	function sitzplatzSchluessel(reihe: string, spalte: number): string {
17	  return `${reihe}-${spalte}`;
18	}
19	
20	@Component({
21	  selector: 'app-sitzplatzauswahl',
22	  imports: [CommonModule, FormsModule, RouterLink],
23	  templateUrl: './sitzplatzauswahl.html',
24	  styleUrl: './sitzplatzauswahl.scss'
25	})
26	export class Sitzplatzauswahl {
27	  private readonly route = inject(ActivatedRoute);
28	  private readonly router = inject(Router);
29	  private readonly veranstaltungenService = inject(VeranstaltungenService);
30	  private readonly buchungenService = inject(BuchungenService);
31	
32	  protected readonly veranstaltungId = this.route.snapshot.paramMap.get('id')!;
33	
34	  readonly veranstaltung = signal<VeranstaltungDetail | null>(null);
35	  readonly sitzplan = signal<Sitzplan | null>(null);
36	  readonly loading = signal(true);
37	  readonly ladeFehler = signal<string | null>(null);
38	
39	  readonly auswahl = signal<Map<string, AusgewaehlterSitzplatz>>(new Map());
40	
41	  name = '';
42	  email = '';
43	  readonly wirdGebucht = signal(false);
44	  readonly buchungsFehler = signal<string | null>(null);
45	
46	  readonly sitzplatzZeilen = computed(() => {
47	    const plan = this.sitzplan();
48	    if (!plan) {
49	      return [];
50	    }
51	    return plan.raum.reihen.map((reihe) => ({
52	      reihe,
53	      plaetze: plan.sitzplaetze.filter((s) => s.reihe === reihe)
54	    }));
55	  });
56	
57	  readonly ausgewaehlteListe = computed(() =>
58	    Array.from(this.auswahl().values()).sort((a, b) => (a.reihe === b.reihe ? a.spalte - b.spalte : a.reihe.localeCompare(b.reihe)))
59	  );
60	
61	  readonly gesamtpreis = computed(() => {
62	    const plan = this.sitzplan();
63	    if (!plan) {
64	      return 0;
65	    }
66	    const preise = new Map(plan.preiskategorien.map((p) => [p.id, p.preis]));
67	    return this.ausgewaehlteListe().reduce((summe, s) => summe + (preise.get(s.preiskategorieId) ?? 0), 0);
68	  });
69	
70	  constructor() {
71	    this.ladeDaten();
72	  }
73	
74	  private ladeDaten(): void {
75	    this.loading.set(true);
76	    this.ladeFehler.set(null);
77	
78	    this.veranstaltungenService.getDetail(this.veranstaltungId).subscribe({
79	      next: (veranstaltung) => this.veranstaltung.set(veranstaltung)
80	    });
81	
82	    this.veranstaltungenService.getSitzplan(this.veranstaltungId).subscribe({
83	      next: (sitzplan) => {
84	        this.sitzplan.set(sitzplan);
85	        this.loading.set(false);
86	      },
87	      error: () => {
88	        this.ladeFehler.set('Der Sitzplan konnte nicht geladen werden.');
89	        this.loading.set(false);
90	      }
91	    });
92	  }
93	
94	  istAusgewaehlt(sitzplatz: Sitzplatz): boolean {
95	    return this.auswahl().has(sitzplatzSchluessel(sitzplatz.reihe, sitzplatz.spalte));
96	  }
97	
98	  sitzplatzKlasse(sitzplatz: Sitzplatz): string {
99	    if (sitzplatz.typ === 'Gang') {
100	      return 'sitz sitz--gang';
101	    }
102	    if (sitzplatz.status === 'Belegt') {
103	      return 'sitz sitz--belegt';
104	    }
105	    if (this.istAusgewaehlt(sitzplatz)) {
106	      return 'sitz sitz--ausgewaehlt';
107	    }
108	    return 'sitz sitz--frei';
109	  }
110	
111	  sitzplatzKlicken(sitzplatz: Sitzplatz): void {
112	    if (sitzplatz.typ === 'Gang' || sitzplatz.status === 'Belegt') {
113	      return;
114	    }
115	
116	    const schluessel = sitzplatzSchluessel(sitzplatz.reihe, sitzplatz.spalte);
117	    const neueAuswahl = new Map(this.auswahl());
118	
119	    if (neueAuswahl.has(schluessel)) {
120	      neueAuswahl.delete(schluessel);
