  zuruecksetzen(): void {
    this.von = '';
    this.bis = '';
    this.spielstaetteId = '';
    this.ladeVeranstaltungen();
  }

  private ladeVeranstaltungen(): void {
    this.loading.set(true);
    this.error.set(null);
